<div class="panel"><h5 class="fw-bold">Mahasiswa Perwalian</h5><div class="table-responsive"><table class="table"><thead><tr><th>NIM</th><th>Nama</th><th>Angkatan</th><th>Foto</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= esc($r['nim']) ?></td><td><?= esc($r['nama']) ?></td><td><?= esc($r['angkatan']) ?></td><td><?php if($r['foto']): ?><img class="avatar" src="<?= base_url('uploads/foto/'.$r['foto']) ?>"><?php else: ?>-<?php endif ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="4" class="text-center muted">Belum ada mahasiswa perwalian.</td></tr><?php endif ?></tbody></table></div></div>